package main

import (
	"fmt"
	"strings"
)

func main() {
	var s string
	fmt.Scan(&s)
	target := "CODEFORCES"
	n := len(s)
	m := len(target)

	if n < m {
		fmt.Println("NO")
		return
	}

	found := false
	for i := 0; i <= m; i++ {
		prefix := target[:i]
		suffix := target[i:]
		if strings.HasPrefix(s, prefix) && strings.HasSuffix(s, suffix) {
			found = true
			break
		}
	}

	if found {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	s := scanner.Text()

	target := "CODEFORCES"
	n := len(s)

	if n < len(target) {
		fmt.Println("NO")
		return
	}

	found := false
	for i := 0; i <= len(target); i++ {
		prefix := s[:i]
		suffixLen := len(target) - i
		suffix := s[n-suffixLen:]
		if prefix+suffix == target {
			found = true
			break
		}
	}

	if found {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

